<?php require __DIR__ . "/vendor/autoload.php"; $app = require_once __DIR__ . "/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $founder = App\Models\User::where("email", "founder@test.com")->first(); if(!$founder) { echo "Founder not found\n"; exit; } $companyAccess = App\Models\UserCompanyAccess::where("user_id", $founder->id)->first(); if(!$companyAccess) { echo "Founder company access not found\n"; exit; } $companyId = $companyAccess->company_id; $investorRole = App\Models\Role::where("name", "like", "%investor%")->orWhere("name", "like", "%cfo%")->first(); if(!$investorRole) { echo "Investor role not found. Available roles:\n"; foreach(App\Models\Role::all() as $r) echo $r->id . " - " . $r->name . "\n"; exit; } $investor = App\Models\User::firstOrCreate(["email" => "investorviewer@test.com"], ["name" => "Investor Viewer", "password" => bcrypt("password123"), "role_id" => $investorRole->id]); App\Models\UserCompanyAccess::firstOrCreate(["user_id" => $investor->id, "company_id" => $companyId]); echo "Success! Created investorviewer@test.com with password: password123. Role: " . $investorRole->name . "\n";
